class Solution {
    public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
        if (buckets <= 1) {
            return 0;
        }
        int statesPerPig = minutesToTest / minutesToDie + 1;
        int maxBucketLabel = buckets - 1;
        int pigs = 0;
        while (maxBucketLabel > 0) {
            pigs++;
            maxBucketLabel /= statesPerPig;
        }
        return pigs;
    }
}

class Solution {
    public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
        int statesPerPig = minutesToTest / minutesToDie + 1;
        int low = 0;
        int high = 1;
        while (!canCover(high, statesPerPig, buckets)) {
            high *= 2;
        }
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canCover(mid, statesPerPig, buckets)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canCover(int pigs, int statesPerPig, int buckets) {
        long covered = 1;
        for (int i = 0; i < pigs && covered < buckets; i++) {
            covered *= statesPerPig;
        }
        return covered >= buckets;
    }
}

class Solution {
    public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
        if (buckets <= 1) {
            return 0;
        }
        int statesPerPig = minutesToTest / minutesToDie + 1;
        int pigs = (int) Math.ceil(Math.log(buckets) / Math.log(statesPerPig));
        while (pigs > 0 && powerAtLeast(statesPerPig, pigs - 1, buckets)) {
            pigs--;
        }
        while (!powerAtLeast(statesPerPig, pigs, buckets)) {
            pigs++;
        }
        return pigs;
    }

    private boolean powerAtLeast(int base, int exponent, int target) {
        long product = 1;
        for (int i = 0; i < exponent && product < target; i++) {
            product *= base;
        }
        return product >= target;
    }
}

class Solution {
    public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
        int statesPerPig = minutesToTest / minutesToDie + 1;
        int pigs = 0;
        while (countOutcomeVectors(pigs, statesPerPig, buckets) < buckets) {
            pigs++;
        }
        return pigs;
    }

    private int countOutcomeVectors(int pigs, int statesPerPig, int limit) {
        if (pigs == 0) {
            return 1;
        }
        int total = 0;
        for (int state = 0; state < statesPerPig && total < limit; state++) {
            int remainingLimit = limit - total;
            total += countOutcomeVectors(pigs - 1, statesPerPig, remainingLimit);
        }
        return Math.min(total, limit);
    }
}
